<?php

declare(strict_types=1);

/**
 * Reads out why the server is failing, and then asks to be deleted.
 *
 * GENERATED by tools/live/build-live.mjs — edit tools/live/templates/diagnose.php.
 *
 * APP_DEBUG=false keeps stack traces out of API responses, which is correct and
 * also why a live 500 says nothing useful in a browser. The exception is in
 * storage/logs — and storage/ is denied to the web, correctly. This page is the
 * one sanctioned way to read it, plus the handful of environment facts that
 * explain most of what goes wrong on a shared host.
 *
 * Gated on SETUP_TOKEN in .env exactly like setup.php: blank ⇒ inert.
 */

use Iced\Kernel\Application;
use Iced\Kernel\Database;
use Iced\Support\Config;
use Iced\Support\Env;

/** @var string $root */
$root = require __DIR__ . '/api/v1/_backend.php';

require $root . '/autoload.php';

$app = Application::boot($root);
$container = $app->container;

$expected = Env::string('SETUP_TOKEN');
$supplied = is_string($_GET['token'] ?? null) ? $_GET['token'] : '';

$html = static fn (string $text): string => htmlspecialchars($text, ENT_QUOTES, 'UTF-8');

$fatal = null;
$sections = [];

if ($expected === '') {
    $fatal = 'SETUP_TOKEN is blank in .env, so this page is switched off. Set it to any long '
        . 'random string, reload, then blank it again and delete this file when you are done.';
} elseif (!hash_equals($expected, $supplied)) {
    $fatal = $supplied === ''
        ? 'Add ?token=... to the address. The token is SETUP_TOKEN in .env.'
        : 'That token does not match SETUP_TOKEN in .env.';
} else {
    /* ── 1. PHP itself ──────────────────────────────────────────────────── */
    $algos = password_algos();
    $hasArgon = in_array('argon2id', $algos, true);

    $php = [
        'version' => PHP_VERSION,
        'sapi' => PHP_SAPI,
        'password_algos()' => implode(', ', $algos) ?: '(none!)',
        'argon2id available' => $hasArgon ? 'yes' : 'NO  <-- see the note below',
    ];

    foreach (['pdo_mysql', 'mbstring', 'openssl', 'gd', 'json', 'fileinfo'] as $extension) {
        $php['ext ' . $extension] = extension_loaded($extension) ? 'loaded' : 'MISSING';
    }

    $sections['PHP'] = $php;

    /* A real hash + verify, because "the extension is loaded" and "the call
       works" are different claims and only the second one matters. */
    $hashCheck = [];

    try {
        $probe = password_hash('probe', $hasArgon ? PASSWORD_ARGON2ID : PASSWORD_BCRYPT);
        $hashCheck['password_hash'] = 'ok (' . substr((string) $probe, 0, 12) . '…)';
        $hashCheck['password_verify'] = password_verify('probe', (string) $probe) ? 'ok' : 'FAILED';
    } catch (Throwable $error) {
        $hashCheck['password_hash'] = 'THREW: ' . $error->getMessage();
    }

    $sections['Password hashing'] = $hashCheck;

    /* ── 2. Writable storage ────────────────────────────────────────────── */
    $storage = [];

    foreach (['storage', 'storage/logs', 'storage/cache', 'storage/media'] as $relative) {
        $path = $root . '/' . $relative;
        $storage[$relative] = !is_dir($path)
            ? 'MISSING'
            : (is_writable($path) ? 'writable' : 'NOT WRITABLE  <-- chmod 755, or 775');
    }

    $sections['Storage'] = $storage;

    /* ── 3. The database ────────────────────────────────────────────────── */
    /** @var Config $config */
    $config = $container->get(Config::class);
    /** @var Database $db */
    $db = $container->get(Database::class);

    $database = [
        'host' => $config->string('database.host') . ':' . $config->int('database.port', 3306),
        'name' => $config->string('database.name'),
        'user' => $config->string('database.user'),
    ];

    try {
        $db->pdo();
        $database['connection'] = 'ok (' . $db->flavour() . ')';

        foreach (['schema_migrations', 'users', 'products', 'store_settings', 'roles'] as $table) {
            try {
                $row = $db->selectOne(sprintf('SELECT COUNT(*) AS n FROM %s', $table));
                $database['rows in ' . $table] = (string) ($row['n'] ?? '?');
            } catch (Throwable $error) {
                $database['rows in ' . $table] = 'QUERY FAILED: ' . $error->getMessage();
            }
        }

        /**
         * Registering mints the customer's public id out of this settings row
         * (Support\IdAllocator — `id_pools` is a key in store_settings, not a
         * table of its own). Missing, registration fails and nothing else does,
         * which is the same shape of symptom as a broken hasher.
         */
        try {
            $setting = $db->selectOne('SELECT COUNT(*) AS n FROM store_settings WHERE `key` = ?', ['id_pools']);
            $database['store_settings.id_pools'] = ((int) ($setting['n'] ?? 0)) > 0
                ? 'present'
                : 'MISSING  <-- registration cannot mint a customer id';
        } catch (Throwable $error) {
            $database['store_settings.id_pools'] = 'CHECK FAILED: ' . $error->getMessage();
        }
    } catch (Throwable $error) {
        $database['connection'] = 'FAILED: ' . $error->getMessage();
    }

    $sections['Database'] = $database;

    /* ── 4. Deployment wiring ───────────────────────────────────────────── */
    $sections['Wiring'] = [
        'backend root' => $root,
        'APP_URL' => $config->string('app.url'),
        'APP_DEBUG' => $config->bool('app.debug') ? 'true' : 'false',
        'SESSION_SECRET' => $config->string('app.session.secret') === '' ? 'BLANK  <-- sessions cannot be signed' : 'set',
        'MAIL_DRIVER' => $config->string('app.mail.driver'),
    ];
}

/* ── 5. The actual exception, from the log ──────────────────────────────── */
$logLines = [];

if ($fatal === null) {
    $files = glob($root . '/storage/logs/app-*.log') ?: [];
    rsort($files);

    if ($files === []) {
        $logLines[] = 'No log files yet in storage/logs. If the directory is NOT WRITABLE above, '
            . 'that is itself the bug: nothing can be recorded, and every request that '
            . 'touches the rate limiter or a session fails.';
    } else {
        $recent = array_slice($files, 0, 2);

        foreach ($recent as $file) {
            $contents = (string) file_get_contents($file);
            $all = preg_split('/\R/', trim($contents)) ?: [];
            $tail = array_slice($all, -40);

            $logLines[] = '───── ' . basename($file) . ' (last ' . count($tail) . ' of ' . count($all) . ' lines)';
            $logLines = array_merge($logLines, $tail);
            $logLines[] = '';
        }
    }
}

http_response_code($fatal === null ? 200 : 403);
header('Content-Type: text/html; charset=utf-8');
header('X-Robots-Tag: noindex, nofollow');

?>
<!doctype html>
