         font: 14px/1.65 ui-monospace, Menlo, Consolas, monospace; }
  main { max-width: 60rem; margin: 0 auto; }
  h1 { font-size: 1.3rem; margin: 0 0 .3rem; }
  h2 { font-size: .95rem; letter-spacing: .08em; text-transform: uppercase;
       color: #8b8b93; margin: 2rem 0 .6rem; }
  p.sub { color: #8b8b93; margin: 0 0 1rem; }
  pre { background: #141416; border: 1px solid #26262b; border-radius: 8px;
        padding: 1rem 1.15rem; overflow-x: auto; white-space: pre-wrap;
        word-break: break-word; margin: 0; }
  .bad { border-color: #7a2b2b; background: #1d1113; color: #ffb4b4; }
  .warn { border: 1px solid #7a5a1f; background: #1c1710; color: #ffd79a;
          border-radius: 8px; padding: 1rem 1.15rem; margin-top: 2rem; }
