  <h1>Iced_out - diagnose</h1>
  <p class="sub">Delete this file when you are done.</p>

<?php if ($fatal !== null) { ?>
  <pre class="bad"><?= $html($fatal) ?></pre>
<?php } else { ?>

<?php foreach ($sections as $title => $rows) { ?>
  <h2><?= $html((string) $title) ?></h2>
  <table>
<?php foreach ($rows as $key => $value) { ?>
    <tr><td class="k"><?= $html((string) $key) ?></td><td><?= str_replace('&lt;--', '<span style="color:#ff9b9b">&lt;--', $html((string) $value)) ?></td></tr>
<?php } ?>
  </table>
<?php } ?>

  <h2>Last errors recorded</h2>
  <pre><?= $html(implode("\n", $logLines)) ?></pre>

  <div class="warn">
    <strong>Reading this:</strong> the line beginning <code>exception</code> in the log is the
    real cause of a 500 — everything before <code>#0</code> is the message.
    If <code>argon2id available</code> says <strong>NO</strong>, registration and login were
    fatal on this host until the build that made the hasher fall back to bcrypt; upload the
    current <code>src/</code> and try again.
    If any Storage row says <strong>NOT WRITABLE</strong>, fix that first — nothing can be
    logged or rate-limited without it.
    <br><br>
    <strong>Then delete <code>diagnose.php</code></strong> and blank <code>SETUP_TOKEN</code> in
    <code>.env</code>.
  </div>
<?php } ?>
</main>
